#!/usr/bin/env python3
"""Install the deterministic, fully offline WILDBOUND vertical-slice source tree."""
from pathlib import Path
import base64,sys,shutil,json
FILES={
    'README.md': '',
    'docs/WILDBOUND_ARCHITECTURE.md': '',
    'app/src/main/assets/www/index.html': '',
    'app/src/main/assets/www/css/wildbound.css': '',
    'app/src/main/AndroidManifest.xml': '',
    'app/src/main/java/com/example/battlezone/MainActivity.kt': '',
    'validate_project.py': '',
    'app/src/main/assets/www/js/wildbound/README.md': '',
    'app/src/main/assets/www/js/wildbound/frontend/boot.js': '',
    'app/src/main/assets/www/js/wildbound/utils/math.js': '',
    'app/src/main/assets/www/js/wildbound/physics/collision.js': '',
    'app/src/main/assets/www/js/wildbound/data/catalog.js': '',
    'app/src/main/assets/www/js/wildbound/rendering/runtime.js': '',
    'app/src/main/assets/www/js/wildbound/ui/interface.js': '',
    'app/src/main/assets/www/js/wildbound/ai/monster-ai.js': '',
    'app/src/main/assets/www/js/wildbound/gameplay/combat.js': '',
    'app/src/main/assets/www/js/wildbound/world/world.js': '',
    'app/src/main/assets/www/js/wildbound/actors/actors.js': '',
    'app/src/main/assets/www/js/wildbound/audio/audio.js': '',
    'app/src/main/assets/www/js/wildbound/backend/mission.js': '',
    'app/src/main/assets/www/js/wildbound/backend/progression.js': '',
    'app/src/main/assets/www/js/wildbound/backend/save.js': '',
    'app/src/main/assets/www/js/wildbound/core/state.js': '',
    'app/src/main/assets/www/js/wildbound/core/config.js': '',
    'app/src/main/res/mipmap-xxxhdpi/ic_launcher.png': '',
    'app/src/main/res/mipmap-xxhdpi/ic_launcher.png': '',
    'app/src/main/res/mipmap-xhdpi/ic_launcher.png': '',
    'app/src/main/res/mipmap-hdpi/ic_launcher.png': '',
    'app/src/main/res/mipmap-mdpi/ic_launcher.png': '',
    'app/src/main/assets/www/models/characters/kaykit_v1_2/License.txt': '',
}
DELETES=['app/src/main/assets/www/js/netplay.js', 'app/src/main/assets/www/js/models.js', 'app/src/main/assets/www/ORIGINAL_GAME_BACKUP_battle-zone-new-ui-1.html']
root=Path(sys.argv[1] if len(sys.argv)>1 else ".").resolve()
for relative,encoded in FILES.items():
 target=root/relative;target.parent.mkdir(parents=True,exist_ok=True);data=base64.b64decode(encoded,validate=True)
 if not target.is_file() or target.read_bytes()!=data:target.write_bytes(data)
for relative in DELETES:
 target=root/relative
 if target.is_file():target.unlink()
www=root/"app/src/main/assets/www"
keep_models={"models/characters/kaykit_v1_2/Animations/gltf/KayKit_AnimatedCharacter_v1.2.glb","models/characters/kaykit_v1_2/License.txt"}
keep_textures={"textures/forest_floor_basecolor.png","textures/forest_floor_roughness.png","textures/forest_floor_height.png"}
for folder,keep in ((www/"models",keep_models),(www/"textures",keep_textures)):
 if folder.exists():
  for item in folder.rglob("*"):
   if item.is_file() and str(item.relative_to(www)).replace("\\","/") not in keep:item.unlink()
  for item in sorted(folder.rglob("*"),reverse=True):
   if item.is_dir():
    try:item.rmdir()
    except OSError:pass
for folder in (www/"audio",www/"assets",www/"branding",www/"characters",www/"loading",www/"sprites"):
 if folder.exists():shutil.rmtree(folder)
manifest_path=www/"PROCEDURAL_ASSET_PROVENANCE.json"
if not manifest_path.is_file():raise SystemExit("Procedural asset provenance manifest missing")
manifest=json.loads(manifest_path.read_text(encoding="utf-8"))
manifest["assets"]=[row for row in manifest.get("assets",[]) if row.get("path") in keep_textures]
if {row.get("path") for row in manifest["assets"]}!=keep_textures:raise SystemExit("PBR texture provenance does not cover the exact retained maps")
manifest_path.write_text(json.dumps(manifest,indent=2,sort_keys=True)+"\n",encoding="utf-8")
for folder,keep in ((www/"js",{"wildbound"}),(www/"css",{"wildbound.css"})):
 if folder.exists():
  for item in folder.rglob("*"):
   if item.is_file() and (item.relative_to(folder).parts[0] not in keep if folder.name=="js" else item.name not in keep):item.unlink()
  for item in sorted(folder.rglob("*"),reverse=True):
   if item.is_dir():
    try:item.rmdir()
    except OSError:pass
index=(www/"index.html").read_text(encoding="utf-8");manifest_xml=(root/"app/src/main/AndroidManifest.xml").read_text(encoding="utf-8")
if "WILDBOUND" not in index or "BATTLE ZONE" in index:raise SystemExit("WILDBOUND entrypoint verification failed")
if "connect-src 'self'" not in index:raise SystemExit("Offline CSP is missing")
if any(x in manifest_xml for x in ("INTERNET","ACCESS_NETWORK_STATE","ACCESS_WIFI_STATE","CHANGE_WIFI_MULTICAST_STATE")):raise SystemExit("Android network permission regression")
if any(not (www/p).is_file() for p in keep_models|keep_textures):raise SystemExit("A required licensed model or PBR texture was pruned")
print("WILDBOUND_TRANSFORMATION_APPLIED",len(FILES),"files; removed legacy UI and unused asset packs")
